package main

import (
	"fmt"
	"io"
	"strings"

	"github.com/urfave/cli/v2"
)

func writeCLIReference(w io.Writer, app *cli.App) error {
	var doc strings.Builder
	doc.WriteString(
		"<!-- Generated by make docs-cli. -->\n" +
			"\n" +
			"# Telegraf Commands & Flags\n" +
			"\n" +
			"```sh\n" +
			"telegraf --config config.toml\n" +
			"telegraf config create --input-filter cpu > telegraf.conf\n" +
			"telegraf version\n" +
			"```\n" +
			"\n" +
			"Use `telegraf help` (alias `telegraf h`) to list commands.\n" +
			"Pass `--help` or `-h` after any command to see its usage.\n" +
			"The service command and service-related flags are Windows only.\n" +
			"\n" +
			"## Global options\n",
	)
	writeCLIFlags(&doc, app.VisibleFlags())
	writeCLICommands(&doc, "telegraf", 2, app.VisibleCommands())
	_, err := io.WriteString(w, doc.String())
	return err
}

func writeCLICommands(doc *strings.Builder, parent string, level int, commands []*cli.Command) {
	for _, command := range commands {
		name := parent + " " + command.Name
		fmt.Fprintf(doc, "\n%s %s\n\n%s\n", strings.Repeat("#", level), name, command.Usage)
		if command.ArgsUsage != "" {
			fmt.Fprintf(doc, "\n`%s %s`\n", name, command.ArgsUsage)
		}
		writeCLIFlags(doc, command.VisibleFlags())
		writeCLICommands(doc, name, level+1, command.VisibleCommands())
	}
}

func writeCLIFlags(doc *strings.Builder, flags []cli.Flag) {
	if len(flags) == 0 {
		return
	}
	doc.WriteByte('\n')
	for _, flag := range flags {
		option := flag.(cli.DocGenerationFlag)
		names := make([]string, 0, len(flag.Names()))
		for _, name := range flag.Names() {
			prefix := "--"
			if len(name) == 1 {
				prefix = "-"
			}
			names = append(names, "`"+prefix+name+"`")
		}
		label := strings.Join(names, ", ")
		if option.TakesValue() {
			label += " `<value>`"
		}
		line := "- " + label + " —"
		for _, word := range strings.Fields(option.GetUsage()) {
			if len(line)+1+len(word) > 80 {
				doc.WriteString(line + "\n")
				line = "  " + word
			} else {
				line += " " + word
			}
		}
		doc.WriteString(line + "\n")
	}
}
